import type { DrillContent } from '../types';

export const DRILL_CONTENT: Record<string, DrillContent> = {
  tower_t2:{t:'Tower T2 — Composite 87 (Best)',s:'Rank 1 of 4 · Improving',b:`<div class="dsec"><div class="dst">Six-dimension breakdown</div><div class="drow"><span class="dl">SLA Compliance</span><span class="dv" style="color:var(--for)">92%</span></div><div class="drow"><span class="dl">Patrol / Security</span><span class="dv" style="color:var(--for)">96%</span></div><div class="drow"><span class="dl">Club Activation</span><span class="dv" style="color:var(--for)">68%</span></div><div class="drow"><span class="dl">Fitout Approval Speed</span><span class="dv" style="color:var(--for)">2.1 days · 22% rejected</span></div><div class="drow"><span class="dl">Staffing Coverage</span><span class="dv" style="color:var(--for)">94%</span></div><div class="drow"><span class="dl">Possession CSAT</span><span class="dv" style="color:var(--for)">4.3/5</span></div></div><div class="dsec"><div class="dst">Why T2 leads</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--for)">T2 has the highest app adoption (86%), the fastest fitout approval speed, and the lowest rejection rate of any tower. No single metric is dragging it down — this is what a well-run tower looks like on every dimension the leaderboard tracks.</div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Use T2's fitout workflow and onboarding approach as the template when fixing FM and T3.</div></div>`,f:`<button class="btn" onclick="swTabById('t-ov');closeD()">View Overview</button>`},
  tower_t1:{t:'Tower T1 — Composite 74',s:'Rank 2 of 4 · Stable',b:`<div class="dsec"><div class="dst">Six-dimension breakdown</div><div class="drow"><span class="dl">SLA Compliance</span><span class="dv" style="color:var(--sky)">78%</span></div><div class="drow"><span class="dl">Patrol / Security</span><span class="dv" style="color:var(--for)">90%</span></div><div class="drow"><span class="dl">Club Activation</span><span class="dv" style="color:var(--crim)">41%</span></div><div class="drow"><span class="dl">Fitout Approval Speed</span><span class="dv" style="color:var(--amb)">3.4 days · 45% rejected</span></div><div class="drow"><span class="dl">Staffing Coverage</span><span class="dv" style="color:var(--sky)">85%</span></div><div class="drow"><span class="dl">Possession CSAT</span><span class="dv" style="color:var(--sky)">3.8/5</span></div></div><div class="dsec"><div class="dst">Why T1 sits at #2</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--sky)">T1 has solid app adoption (70%) and reasonable operations, but Club Activation at 41% is the clear laggard — well below T2's 68%. This is the one dimension pulling T1's composite down from a leadership position.</div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Focus on club membership activation specifically in T1 — the other 5 dimensions are already close to Tower T2's level.</div></div>`,f:`<button class="btn" onclick="swTabById('t-cl');closeD()">View Club &amp; Facilities</button>`},
  tower_t3:{t:'Tower T3 — Composite 61',s:'Rank 3 of 4 · Declining',b:`<div class="dsec"><div class="dst">Six-dimension breakdown</div><div class="drow"><span class="dl">SLA Compliance</span><span class="dv" style="color:var(--amb)">65%</span></div><div class="drow"><span class="dl">Patrol / Security</span><span class="dv" style="color:var(--sky)">88%</span></div><div class="drow"><span class="dl">Club Activation</span><span class="dv" style="color:var(--crim)">22%</span></div><div class="drow"><span class="dl">Fitout Approval Speed</span><span class="dv" style="color:var(--crim)">4.8 days · 58% rejected</span></div><div class="drow"><span class="dl">Staffing Coverage</span><span class="dv" style="color:var(--amb)">79%</span></div><div class="drow"><span class="dl">Possession CSAT</span><span class="dv" style="color:var(--amb)">3.5/5</span></div></div><div class="dsec"><div class="dst">Why T3 is declining</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">T3 has the lowest app adoption of any tower (17%) — this alone explains weak Club Activation and likely contributes to the low SLA compliance too, since residents who aren't on the app may not be raising tickets through the tracked channel at all, or engaging with communications about ticket status.</div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Fix app adoption first (see Community tab) — several of T3's weak metrics may improve as a downstream effect, without touching those systems directly.</div></div>`,f:`<button class="btn" onclick="swTabById('t-co');closeD()">View Community — Adoption</button>`},
  tower_fm:{t:'Tower FM — Composite 52 (Worst)',s:'Rank 4 of 4 · Declining · Likely driving society-wide CSAT decline',b:`<div class="dsec"><div class="dst">Six-dimension breakdown</div><div class="drow"><span class="dl">SLA Compliance</span><span class="dv" style="color:var(--crim)">58%</span></div><div class="drow"><span class="dl">Patrol / Security</span><span class="dv" style="color:var(--sky)">91%</span></div><div class="drow"><span class="dl">Club Activation</span><span class="dv" style="color:var(--crim)">19%</span></div><div class="drow"><span class="dl">Fitout Approval Speed</span><span class="dv" style="color:var(--crim)">5.2 days · 61% rejected</span></div><div class="drow"><span class="dl">Staffing Coverage</span><span class="dv" style="color:var(--amb)">81%</span></div><div class="drow"><span class="dl">Possession CSAT</span><span class="dv" style="color:var(--crim)">3.2/5 — lowest of any tower</span></div></div><div class="dsec"><div class="dst">The cross-reference that matters most</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">The Overview tab flags Possession Timeliness as the one CSAT dimension declining society-wide. FM has the slowest fitout approval speed (5.2 days) and highest rejection rate (61%) of any tower — and the lowest possession CSAT score. This is very likely not a diffuse, society-wide problem — it's FM specifically, showing up in the aggregate number.</div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Fixing FM's fitout workflow is plausibly the single highest-leverage action available — it would improve FM's composite score, the society-wide Possession CSAT, and remove FM's outsized contribution to the overall Fitout rejection rate all at once.</div></div>`,f:`<button class="btn" onclick="swTabById('t-ft');closeD()">View Fitout — FM Priority</button>`},
  possession_csat:{t:'Possession Experience — 3.9/5',s:'BMS → Feedbacks · 5-dimension survey',b:`<div class="dsec"><div class="dst">By dimension</div><div class="drow"><span class="dl">Apartment Quality</span><span class="dv" style="color:var(--for)">4.3/5 ↑</span></div><div class="drow"><span class="dl">Possession Timeliness</span><span class="dv" style="color:var(--crim)">3.1/5 ↓</span></div><div class="drow"><span class="dl">Services &amp; Infrastructure</span><span class="dv" style="color:var(--for)">4.0/5 ↑</span></div><div class="drow"><span class="dl">Process Ease</span><span class="dv" style="color:var(--for)">3.9/5 ↑</span></div><div class="drow"><span class="dl">Booking→Possession Service</span><span class="dv" style="color:var(--for)">4.2/5 ↑</span></div></div><div class="dsec"><div class="dst">Trend — 6 months</div><div class="drow"><span class="dl">Overall CSAT</span><span class="dv">3.7 → 3.9</span></div><div class="drow"><span class="dl">Possession Timeliness</span><span class="dv" style="color:var(--crim)">3.6 → 3.1 (only dimension declining)</span></div></div><div class="dsec"><div class="dst">Why this is the priority dimension</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">Every other dimension improved over the last 6 months — only Possession Timeliness declined. This dimension measures how long residents waited for handover, which is directly influenced by Fitout and Move In approval speed. With 24 of 38 fitout requests still Pending and 0 closed this month, that backlog is the most likely driver — not a construction or infrastructure issue.</div></div>`,f:`<button class="btn" onclick="swTabById('t-ft');closeD()">Open Fitout Tab</button><button class="btng" onclick="toast('Feedback detail opened','d');closeD()">View Individual Responses</button>`},
  resp_breach:{t:'42 Response Escalation Breaches',s:'First-response SLA not being met',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">Example: FM · Office</div><div class="dflat-res">Ticket #S010-10045 · Electrical · Assigned to Anya Pande</div></div></div><div class="dsec"><div class="dst">What this means</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">Response Escalation = Breached means the team did not send a first acknowledgement/response within the target Response TAT. The ticket was created but not picked up in time.</div></div><div class="dsec"><div class="dst">Scale of problem</div><div class="drow"><span class="dl">Total tickets</span><span class="dv">59</span></div><div class="drow"><span class="dl">Response Breached</span><span class="dv" style="color:var(--crim)">42 (71%)</span></div><div class="drow"><span class="dl">Response Achieved</span><span class="dv" style="color:var(--for)">17 (29%)</span></div></div><div class="dsec"><div class="dst">Likely causes</div><div style="font-size:11px;line-height:1.7">1. Tickets not being assigned to staff promptly<br>2. Staff unaware of new ticket arrival<br>3. Response TAT targets set too aggressively<br>4. Insufficient manpower for ticket volume</div></div>`,f:`<button class="btn" onclick="toast('Assignment review opened','ok');closeD()">Review Unassigned Tickets</button><button class="btng" onclick="toast('TAT settings opened','d');closeD()">Review TAT Settings</button>`},
  res_breach:{t:'38 Resolution Escalation Breaches',s:'Resolution SLA not being met',b:`<div class="dsec"><div class="dst">What this means</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--wa)">Resolution Escalation = Breached means the ticket was eventually acknowledged but not resolved within the Resolution TAT window. Tickets were picked up but not completed in time.</div></div><div class="dsec"><div class="dst">Scale</div><div class="drow"><span class="dl">Resolution Breached</span><span class="dv" style="color:var(--crim)">38 (64%)</span></div><div class="drow"><span class="dl">Resolution Achieved</span><span class="dv" style="color:var(--for)">21 (36%)</span></div></div>`,f:`<button class="btn" onclick="toast('Aging tickets opened','ok');closeD()">Review Aging Tickets</button>`},
  fitout_pending:{t:'24 Fitout Requests Pending',s:'All requests in Pending · 0 closed this month',b:`<div class="dsec"><div class="dst">Status breakdown</div><div class="drow"><span class="dl">Total requests</span><span class="dv">38</span></div><div class="drow"><span class="dl">Pending</span><span class="dv" style="color:var(--crim)">24</span></div><div class="drow"><span class="dl">Closed</span><span class="dv">0</span></div><div class="drow"><span class="dl">Rejected</span><span class="dv">0</span></div></div><div class="dsec"><div class="dst">Action required</div><div style="font-size:11px;line-height:1.7">For each pending request, decide: Approve, Reject, or Request Modification. Contractors associated with these requests may be waiting for clearance before starting work.</div></div>`,f:`<button class="btn" onclick="toast('Fitout queue opened','ok');closeD()">Open Fitout Queue</button>`},
  members_pending:{t:'78 Club Memberships Pending Activation',s:'66% of all members · Immediate action needed',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">Example: FM · Office</div><div class="dflat-res">Sagar Patil · Applied, awaiting activation</div></div></div><div class="dsec"><div class="dst">Membership status</div><div class="drow"><span class="dl">Total members</span><span class="dv">117</span></div><div class="drow"><span class="dl">Active</span><span class="dv" style="color:var(--for)">15 (13%)</span></div><div class="drow"><span class="dl">Pending</span><span class="dv" style="color:var(--crim)">78 (66%)</span></div><div class="drow"><span class="dl">Inactive</span><span class="dv">24 (21%)</span></div></div><div class="dsec"><div class="dst">What Pending means</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px">Pending members have applied or been enrolled but their account hasn't been activated by an admin. They cannot book facilities or access club benefits until activated.</div></div>`,f:`<button class="btn" onclick="toast('Bulk activation opened','ok');closeD()">Bulk Activate Members</button><button class="btng" onclick="toast('Individual review opened','d');closeD()">Review Individual</button>`},
  vis_pending:{t:'18 Visitors Pending Post Approval',s:'1 waiting 70+ minutes at gate',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">T3 · Flat 101</div><div class="dflat-res">Longest-waiting visitor · Host: Resident at T3-101</div></div></div><div class="dsec"><div class="dst">Current queue</div><div class="drow"><span class="dl">Total pending</span><span class="dv" style="color:var(--crim)">18</span></div><div class="drow"><span class="dl">Longest wait</span><span class="dv" style="color:var(--crim)">70+ minutes</span></div><div class="drow"><span class="dl">Approval type needed</span><span class="dv">Post Approval (on-arrival)</span></div></div><div class="dsec"><div class="dst">Why visitors end up here</div><div style="font-size:11px;line-height:1.7">These visitors did not have a Pre-Approval set up ahead of time, so they need real-time clearance. The host receives an approval request via app on arrival — if the host doesn't respond promptly, the visitor waits at the gate.</div></div>`,f:`<button class="btn" onclick="toast('Visitor queue opened','ok');closeD()">Open SmartSecure Queue</button>`},
  vis_pre_approved:{t:'98 Pre-Approved Visitors Today',s:'Host approved before arrival · 42% of total',b:`<div class="dsec"><div class="dst">What Pre-Approved means</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--for)">A visitor is Pre-Approved when the resident registers and approves them in the app before the visitor arrives at the gate. This is the fastest path through security — guards simply verify identity and let them through.</div></div><div class="dsec"><div class="dst">Today</div><div class="drow"><span class="dl">Pre-Approved</span><span class="dv" style="color:var(--for)">98 (42%)</span></div><div class="drow"><span class="dl">Post-Approved</span><span class="dv" style="color:var(--amb)">58 (25%)</span></div></div><div class="dsec"><div class="dst">Opportunity</div><div style="font-size:11px;line-height:1.7">Raising the Pre-Approved share directly reduces gate queue time. Frequent visitors like domestic help and regular delivery agents are the best candidates for resident pre-registration.</div></div>`,f:`<button class="btn" onclick="toast('Pre-approval campaign opened','ok');closeD()">Promote Pre-Registration</button>`},
  vis_post_approved:{t:'58 Post-Approved Visitors Today',s:'Cleared on arrival · Slower than Pre-Approved',b:`<div class="dsec"><div class="dst">What Post-Approved means</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--amb)">A visitor is Post-Approved when the host approves them only after they've already arrived at the gate. This requires the host to respond in real time, which is the main source of gate queue delay.</div></div><div class="dsec"><div class="dst">Impact</div><div class="drow"><span class="dl">Post-Approved today</span><span class="dv" style="color:var(--amb)">58 (25%)</span></div><div class="drow"><span class="dl">Still pending clearance</span><span class="dv" style="color:var(--crim)">18</span></div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Encourage residents to shift frequent visitors to Pre-Approved status. This is the single biggest lever for reducing gate wait times without adding staff.</div></div>`,f:`<button class="btn" onclick="toast('Gate log opened','ok');closeD()">Review Gate Log</button>`},
  vis_wrong_entry:{t:'8 Wrong Entry Attempts Today',s:'Visitors bypassing approval process',b:`<div class="dsec"><div class="dst">What Wrong Entry means</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">Wrong Entry is logged when a visitor enters the society premises without completing the SmartSecure approval flow. This is a security gap — it means the gate is not enforcing the digital entry process for every visitor.</div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Brief gate staff to log every visitor through the SmartSecure app before allowing entry. Zero Wrong Entry should be the target every day.</div></div>`,f:`<button class="btn" onclick="toast('Gate log opened','ok');closeD()">Review Gate Log</button>`},
  vis_approved:{t:'Visitor Approvals — Today',s:'Approved, Partially Approved, Pre-Approved',b:`<div class="dsec"><div class="dst">Approval breakdown</div><div class="drow"><span class="dl">Approved</span><span class="dv" style="color:var(--for)">120</span></div><div class="drow"><span class="dl">Partially Approved</span><span class="dv">28</span></div><div class="drow"><span class="dl">Pre-Approved</span><span class="dv">14</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  vis_rejected:{t:'Rejected Visitors — Today',s:'10 visitors denied entry',b:`<div class="dsec"><div class="dst">Common rejection reasons</div><div class="drow"><span class="dl">Host not found / null</span><span class="dv">5</span></div><div class="drow"><span class="dl">Invalid purpose</span><span class="dv">3</span></div><div class="drow"><span class="dl">Unverified support staff</span><span class="dv">2</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  vehicles_today:{t:'156 Vehicles Tracked Today',s:'Vehicle In/Out · distinct from visitor foot-traffic',b:`<div class="dsec"><div class="dst">Why this is tracked separately</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--sky)">SmartSecure logs vehicles (Member Vehicles vs Guest Vehicles) as a distinct entity from visitor foot-traffic. A visitor can arrive on foot or by vehicle — these are two different gate processes with different queue dynamics.</div></div><div class="dsec"><div class="dst">Split</div><div class="drow"><span class="dl">Member Vehicles</span><span class="dv" style="color:var(--for)">98 (63%)</span></div><div class="drow"><span class="dl">Guest Vehicles</span><span class="dv" style="color:var(--amb)">58 (37%)</span></div></div>`,f:`<button class="btn" onclick="toast('Vehicle log opened','ok');closeD()">Open Vehicle Log</button>`},
  vehicles_member:{t:'98 Member Vehicles Today',s:'Resident-owned · steady throughout the day',b:`<div class="dsec"><div class="dst">Pattern</div><div style="font-size:11px;line-height:1.7">Member vehicle movement stays roughly flat across all hours — residents come and go on their own schedule, not concentrated in any particular window. This is the baseline against which Guest Vehicle spikes stand out.</div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  vehicles_guest:{t:'58 Guest Vehicles Today',s:'37% of total · concentrated in peak hours',b:`<div class="dsec"><div class="dst">Composition</div><div style="font-size:11px;line-height:1.7">Guest Vehicles include contractor vehicles (fitout-related), visitor cars, and delivery vehicles. Unlike Member Vehicles, this category is not evenly spread — it concentrates heavily during the 5–7 PM window.</div></div><div class="dsec"><div class="dst">See also</div><div style="font-size:11px;line-height:1.7">This connects directly to the Peak-Hour Guest Share metric — 62% of all vehicle traffic in the 5–7 PM window is Guest, not Member.</div></div>`,f:`<button class="btn" onclick="openD('vehicles_peak')">View Peak-Hour Detail</button>`},
  vehicles_peak:{t:'62% Guest Vehicle Share — 5–7 PM',s:'vs 15% rest of day · matches foot-traffic peak',b:`<div class="dsec"><div class="dst">The pattern</div><div class="drow"><span class="dl">Guest share, 5–7 PM</span><span class="dv" style="color:var(--crim)">62%</span></div><div class="drow"><span class="dl">Guest share, rest of day</span><span class="dv" style="color:var(--for)">15%</span></div></div><div class="dsec"><div class="dst">Why this is a strong signal, not a coincidence</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">The Hourly Traffic Pattern chart already showed visitor foot-traffic peaking 5–7 PM, attributed to active fitout work. Vehicle data — a completely separate log from visitor foot-traffic — shows the exact same window spiking, driven specifically by Guest (not Member) vehicles. Two independent datasets agreeing this precisely is strong evidence, not a loose correlation.</div></div>`,f:`<button class="btn" onclick="toast('Contractor gate proposal drafted','ok');closeD()">Propose Dedicated Contractor Gate</button>`},
  patrol:{t:'Patrol Compliance — 94%',s:'22/24 checkpoints · 2 missed, both linked to incidents',b:`<div class="dsec"><div class="dst">Today's summary</div><div class="drow"><span class="dl">Total checkpoints</span><span class="dv">24</span></div><div class="drow"><span class="dl">Completed</span><span class="dv" style="color:var(--for)">22 (94%)</span></div><div class="drow"><span class="dl">Missed</span><span class="dv" style="color:var(--crim)">2</span></div></div><div class="dsec"><div class="dst">The correlation</div><div class="drow"><span class="dl">Gate 3 (11:00 PM)</span><span class="dv" style="color:var(--crim)">→ Incident 40 min later</span></div><div class="drow"><span class="dl">Sector B (3:00 AM)</span><span class="dv" style="color:var(--amb)">→ Ticket next morning</span></div></div><div class="dsec"><div class="dst">Why this changes the picture</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">94% compliance sounds acceptable in isolation. But both of the 2 missed checkpoints this week produced a real, logged consequence — an attempted unauthorized entry and a Helpdesk ticket. The same guard missed both. This is a routing/staffing pattern with demonstrated risk, not a rounding error in a compliance percentage.</div></div>`,f:`<button class="btn" onclick="toast('Guard route reassignment opened','ok');closeD()">Reassign Guard Route</button>`},
  patrol_incident_1:{t:'Incident #INC-0234',s:'Gate 3 · Attempted unauthorized entry',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">Gate 3 Perimeter</div><div class="dflat-res">Logged 11:40 PM · 40 minutes after missed checkpoint</div></div></div><div class="dsec"><div class="dst">Incident detail</div><div class="drow"><span class="dl">Type</span><span class="dv">Attempted unauthorized entry</span></div><div class="drow"><span class="dl">Reported by</span><span class="dv">Night shift guard (adjacent gate)</span></div><div class="drow"><span class="dl">Outcome</span><span class="dv" style="color:var(--amb)">Individual left before identification</span></div></div><div class="dsec"><div class="dst">Why this matters</div><div style="font-size:11px;line-height:1.7">Gate 3's scheduled 11:00 PM patrol round was missed. An unidentified individual was seen near the same perimeter 40 minutes later. This is exactly the kind of gap a patrol round exists to catch — the missed checkpoint is not incidental to this incident.</div></div>`,f:`<button class="btn" onclick="toast('Incident report opened','ok');closeD()">Open Full Incident Report</button>`},
  patrol_incident_2:{t:'Ticket #S010-10061',s:'Sector B · Damaged common area fixture',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">Sector B Stairwell</div><div class="dflat-res">Reported 7:15 AM · Reactive ticket, resident-raised</div></div></div><div class="dsec"><div class="dst">Ticket detail</div><div class="drow"><span class="dl">Category</span><span class="dv">Electrical — common area lighting</span></div><div class="drow"><span class="dl">Raised by</span><span class="dv">Resident, next morning</span></div><div class="drow"><span class="dl">Priority</span><span class="dv">P2 — High</span></div></div><div class="dsec"><div class="dst">Why this matters</div><div style="font-size:11px;line-height:1.7">Sector B's scheduled 3:00 AM patrol round was missed. Had the round happened, a damaged fixture in a stairwell is exactly the kind of hazard a patrol would normally catch and log overnight — instead it was only discovered when a resident reported it hours later.</div></div>`,f:`<button class="btn" onclick="swTabById('t-op');closeD()">Open in Helpdesk</button>`},
  tickets_all:{t:'59 Total Tickets — This Period',s:'BMS Helpdesk breakdown',b:`<div class="dsec"><div class="dst">Status</div><div class="drow"><span class="dl">Open</span><span class="dv" style="color:var(--crim)">49</span></div><div class="drow"><span class="dl">Work in Progress</span><span class="dv" style="color:var(--amb)">8</span></div><div class="drow"><span class="dl">Closed</span><span class="dv" style="color:var(--for)">10</span></div><div class="drow"><span class="dl">Completed</span><span class="dv" style="color:var(--for)">10</span></div></div><div class="dsec"><div class="dst">Ticket types</div><div class="drow"><span class="dl">Complaints</span><span class="dv">45</span></div><div class="drow"><span class="dl">Suggestions</span><span class="dv">8</span></div><div class="drow"><span class="dl">Requests</span><span class="dv">0</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  tickets_open:{t:'49 Open Tickets',s:'Pending + Work in Progress',b:`<div class="dsec"><div class="dst">Open ticket detail</div><div class="drow"><span class="dl">Pending</span><span class="dv">41</span></div><div class="drow"><span class="dl">Work in Progress</span><span class="dv">8</span></div></div><div class="dsec"><div class="dst">Top categories (open)</div><div class="drow"><span class="dl">Housekeeping</span><span class="dv">~22</span></div><div class="drow"><span class="dl">Electrical</span><span class="dv">~14</span></div><div class="drow"><span class="dl">Civil</span><span class="dv">~8</span></div><div class="drow"><span class="dl">Other</span><span class="dv">~5</span></div></div>`,f:`<button class="btn" onclick="toast('Open tickets view opened','ok');closeD()">View in BMS Helpdesk</button>`},
  complaints:{t:'45 Complaints Open',s:'76% of all tickets are complaints',b:`<div class="dsec"><div class="dst">Ticket type split</div><div class="drow"><span class="dl">Complaints</span><span class="dv" style="color:var(--crim)">45 (76%)</span></div><div class="drow"><span class="dl">Suggestions</span><span class="dv">8 (14%)</span></div><div class="drow"><span class="dl">Requests</span><span class="dv">0</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  proactive:{t:'Proactive Ticket Ratio — 59%',s:'Target: 70%+ proactive',b:`<div class="dsec"><div class="dst">Breakdown</div><div class="drow"><span class="dl">Proactive tickets</span><span class="dv" style="color:var(--for)">35 (59%)</span></div><div class="drow"><span class="dl">Reactive tickets</span><span class="dv" style="color:var(--crim)">24 (41%)</span></div></div><div class="dsec"><div class="dst">Why this matters</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px">Proactive tickets are raised by your maintenance team before residents notice a problem. A high proactive ratio means the team is ahead of issues. 70%+ is the recommended target for a well-run society.</div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  members_all:{t:'117 Club Members — All Statuses',s:'CMS Club Members',b:`<div class="dsec"><div class="dst">Status breakdown</div><div class="drow"><span class="dl">Active</span><span class="dv" style="color:var(--for)">15 (13%)</span></div><div class="drow"><span class="dl">Inactive</span><span class="dv">24 (21%)</span></div><div class="drow"><span class="dl">Pending</span><span class="dv" style="color:var(--crim)">78 (66%)</span></div></div>`,f:`<button class="btn" onclick="toast('Members list opened','ok');closeD()">Open Club Members</button>`},
  expired_mem:{t:'Expired Memberships — Renewal Needed',s:'Members whose plan period ended',b:`<div class="dsec"><div class="dst">Expired members seen</div><div class="drow"><span class="dl">Ajay Ghenand (FM-Offices)</span><span class="dv" style="color:var(--crim)">Summer Plan expired</span></div><div class="drow"><span class="dl">Sagar Patil (FM-Offices)</span><span class="dv" style="color:var(--crim)">Plan expired 31 May</span></div></div><div class="dsec"><div class="dst">Plan: Summer Plan</div><div class="drow"><span class="dl">Price</span><span class="dv">₹20,000/month</span></div><div class="drow"><span class="dl">Type</span><span class="dv">Monthly</span></div></div>`,f:`<button class="btn" onclick="toast('Renewal outreach started','ok');closeD()">Send Renewal Reminder</button>`},
  bookings_today:{t:'12 Facility Bookings Today',s:'Yoga Room, Swimming Pool, Banquet Hall',b:`<div class="dsec"><div class="dst">Facilities in use</div><div class="drow"><span class="dl">Yoga Room Test</span><span class="dv">5 bookings</span></div><div class="drow"><span class="dl">Swimming Pool</span><span class="dv">3 bookings</span></div><div class="drow"><span class="dl">Banquet Hall</span><span class="dv">2 bookings</span></div><div class="drow"><span class="dl">Running Track</span><span class="dv">2 bookings</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  payments_cls:{t:'CMS Payments — Status Review',s:'FacilityBooking · ClubMember · LockAccountBill',b:`<div class="dsec"><div class="dst">Payment types</div><div class="drow"><span class="dl">FacilityBooking</span><span class="dv">Facility reservation payments</span></div><div class="drow"><span class="dl">ClubMember</span><span class="dv">Membership fee payments</span></div><div class="drow"><span class="dl">LockAccountBill</span><span class="dv">Account charges (₹200 seen)</span></div></div><div class="dsec"><div class="dst">Status</div><div class="drow"><span class="dl">SUCCESS</span><span class="dv" style="color:var(--for)">Most records</span></div><div class="drow"><span class="dl">PENDING</span><span class="dv" style="color:var(--amb)">6 records</span></div><div class="drow"><span class="dl">failure</span><span class="dv" style="color:var(--crim)">1 record (Govind patil)</span></div></div>`,f:`<button class="btn" onclick="toast('Payments view opened','ok');closeD()">Open CMS Payments</button>`},
  fitout_all:{t:'38 Fitout Requests — All',s:'Fitout + Move In combined',b:`<div class="dsec"><div class="dst">Type split</div><div class="drow"><span class="dl">Fitout (renovation)</span><span class="dv">32</span></div><div class="drow"><span class="dl">Move In (new resident)</span><span class="dv">6</span></div></div><div class="dsec"><div class="dst">Status</div><div class="drow"><span class="dl">Pending</span><span class="dv" style="color:var(--crim)">24</span></div><div class="drow"><span class="dl">No status set</span><span class="dv">14</span></div><div class="drow"><span class="dl">Closed/Rejected</span><span class="dv">0</span></div></div>`,f:`<button class="btn" onclick="toast('Fitout module opened','ok');closeD()">Open Fitout Module</button>`},
  fitout_deviations:{t:'7 Open Fitout Deviations',s:'Work done outside approved scope',b:`<div class="dsec"><div class="dst">Deviation types</div><div class="drow"><span class="dl">Structural</span><span class="dv" style="color:var(--crim)">2 (highest risk)</span></div><div class="drow"><span class="dl">Electrical</span><span class="dv" style="color:var(--amb)">2</span></div><div class="drow"><span class="dl">Plumbing</span><span class="dv">2</span></div><div class="drow"><span class="dl">Aesthetic</span><span class="dv">1</span></div></div><div class="dsec"><div class="dst">Action required</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">Structural deviations require physical inspection and engineer sign-off. Issue stop-work notices where load-bearing modifications were made without approval.</div></div>`,f:`<button class="btn" onclick="toast('Deviations view opened','ok');closeD()">View Fitout Deviations</button>`},
  fitout_movein:{t:'6 Move In Requests Pending',s:'New residents wanting to occupy flats',b:`<div class="dsec"><div class="dst">Move In vs Fitout</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px">Move In requests are from new residents who want to move into their flat. This is different from Fitout (renovation). Move In needs flat handover verification, key handover confirmation, and entry permission for movers.</div></div><div class="dsec"><div class="dst">Known Move In requests</div><div class="drow"><span class="dl">Sarang Kumar · FM-101</span><span class="dv">04 May 2026</span></div><div class="drow"><span class="dl">Komal Demo · FM-Office</span><span class="dv">23 Apr 2026</span></div></div>`,f:`<button class="btn" onclick="toast('Move In queue opened','ok');closeD()">Review Move In Queue</button>`},
  fitout_req_det:{t:'Fitout Request Detail',s:'Request information and history',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">T1 · Flat 201</div><div class="dflat-res">Resident: Dinesh Cshinda</div></div></div><div class="dsec"><div class="dst">Request #2867</div><div class="drow"><span class="dl">Type</span><span class="dv">Fitout (renovation)</span></div><div class="drow"><span class="dl">Created By</span><span class="dv" style="color:var(--vio)">Admin</span></div><div class="drow"><span class="dl">Contractor</span><span class="dv">AJ GROUP</span></div><div class="drow"><span class="dl">Contractor Mobile</span><span class="dv">9656444343</span></div><div class="drow"><span class="dl">Request Date</span><span class="dv">29 Apr 2026</span></div><div class="drow"><span class="dl">Status</span><span class="dv" style="color:var(--amb)">Pending</span></div></div>`,f:`<button class="btn" onclick="toast('Request approved','ok');closeD()">Approve</button><button class="btng" onclick="toast('Modification requested','w');closeD()">Need Modification</button><button class="btng" onclick="toast('Request rejected','e');closeD()">Reject</button>`},
  fitout_created_by:{t:'Resident-Raised vs Admin-Raised',s:'16 resident-raised · 22 admin-raised',b:`<div class="dsec"><div class="dst">What this tracks</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--vio)">Fitout requests can be raised two ways: by an admin on behalf of a resident (usually with contractor details already attached), or self-service by the resident directly through the app.</div></div><div class="dsec"><div class="dst">Split</div><div class="drow"><span class="dl">Admin-Raised</span><span class="dv" style="color:var(--vio)">22 (58%)</span></div><div class="drow"><span class="dl">Resident-Raised</span><span class="dv" style="color:var(--crim)">16 (42%)</span></div></div><div class="dsec"><div class="dst">Why the gap matters</div><div style="font-size:11px;line-height:1.7">Admin-raised requests average <strong>1.8 days</strong> to a decision. Resident-raised requests average <strong>4.6 days</strong> — 2.6× slower. The difference is document completeness at submission, not review priority.</div></div>`,f:`<button class="btn" onclick="toast('Resident form checklist opened','ok');closeD()">Add Guided Checklist to Resident Form</button>`},
  fitout_rejection_rate:{t:'55% All-Time Rejection Rate',s:'73 of 132 decided requests rejected',b:`<div class="dsec"><div class="dst">By who raised it</div><div class="drow"><span class="dl">Admin-Raised</span><span class="dv" style="color:var(--for)">30% rejected (of 79 decided)</span></div><div class="drow"><span class="dl">Resident-Raised</span><span class="dv" style="color:var(--crim)">75% rejected (of 53 decided)</span></div></div><div class="dsec"><div class="dst">By request type</div><div class="drow"><span class="dl">Fitout (renovation)</span><span class="dv" style="color:var(--crim)">62% rejected (of 110 decided)</span></div><div class="drow"><span class="dl">Move In</span><span class="dv" style="color:var(--for)">23% rejected (of 22 decided)</span></div></div><div class="dsec"><div class="dst">The compounding pattern</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">Resident-raised requests are already 2.6× slower to decide (4.6 vs 1.8 days) — and now the outcome data shows they're also 2.5× more likely to be rejected outright. These two facts point at the same root cause: the resident-facing form isn't collecting what reviewers need, forcing either delay (follow-up requests) or outright rejection.</div></div>`,f:`<button class="btn" onclick="toast('Resident form redesign started','ok');closeD()">Redesign Resident Intake Form</button>`},
  fitout_deposit_held:{t:'₹4.6L Deposit Currently Held',s:'Across 8 active fitouts in progress',b:`<div class="dsec"><div class="dst">By unit</div><div class="drow"><span class="dl">2761 · Meera Nair (T3)</span><span class="dv">₹30,000</span></div><div class="drow"><span class="dl">2782 · Ananya Rao (T1)</span><span class="dv">₹28,000</span></div><div class="drow"><span class="dl">2790 · Sameer Joshi (T3)</span><span class="dv">₹25,000</span></div><div class="drow"><span class="dl">2801 · Priya Kulkarni (FM)</span><span class="dv">₹30,000</span></div><div class="drow"><span class="dl">2815 · Karan Mehta (T1)</span><span class="dv">₹15,000</span></div><div class="drow"><span class="dl">2822 · Divya Menon (T3)</span><span class="dv">₹25,000</span></div></div><div class="dsec"><div class="dst">What this represents</div><div style="font-size:11px;line-height:1.7">This is money the society is currently holding as a liability against active fitout work — refundable once each unit completes its compliance checklist and finishes work. It should reconcile against the accounting ledger for active fitout deposits.</div></div>`,f:`<button class="btn" onclick="toast('Deposit ledger opened','ok');closeD()">Reconcile Against Accounting Ledger</button>`},
  fitout_refund_due:{t:'₹1.25L Refund Due — Next 30 Days',s:'5 fitouts approaching completion',b:`<div class="dsec"><div class="dst">Upcoming refunds</div><div class="drow"><span class="dl">2761 · Meera Nair</span><span class="dv" style="color:var(--amb)">12 Jul 2026 · ₹30,000</span></div><div class="drow"><span class="dl">2790 · Sameer Joshi</span><span class="dv" style="color:var(--amb)">18 Jul 2026 · ₹25,000</span></div><div class="drow"><span class="dl">2815 · Karan Mehta</span><span class="dv" style="color:var(--amb)">15 Jul 2026 · ₹15,000</span></div><div class="drow"><span class="dl">2822 · Divya Menon</span><span class="dv" style="color:var(--amb)">22 Jul 2026 · ₹25,000</span></div></div><div class="dsec"><div class="dst">Separate concern — rejected-request backlog</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">This ₹1.25L is scheduled, expected refund activity. Separately, ₹2.1L from 9 already-rejected requests remains unrefunded with no schedule at all — that's the more urgent cleanup item, see the Liability Cleanup risk card above.</div></div>`,f:`<button class="btn" onclick="toast('Refund processing scheduled','ok');closeD()">Prepare Refund Batch</button>`},
  fitout_compliance:{t:'Compliance Checklist — 67% Avg Completion',s:'8 active fitouts · 6 required documents each',b:`<div class="dsec"><div class="dst">The 6 required documents</div><div style="font-size:11px;line-height:1.7">Hot Work Permit · Security Clearance Form · Contractor Employee List · ID Card Issuance · Fitout Commencement Letter · Refund Checklist</div></div><div class="dsec"><div class="dst">Lowest completion</div><div class="drow"><span class="dl">2801 · Priya Kulkarni</span><span class="dv" style="color:var(--crim)">2/6 — missing 4 documents</span></div><div class="drow"><span class="dl">2782 · Ananya Rao</span><span class="dv" style="color:var(--crim)">3/6 — missing Hot Work Permit, Security Clearance</span></div></div><div class="dsec"><div class="dst">Why this matters</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--amb)">Hot Work Permit and Security Clearance are the two most common blockers, and both require sign-off from outside the fitout team (fire safety, security desk). A flat "pending" status hides this — knowing exactly which document is missing means the admin can follow up with the right person instead of chasing the resident.</div></div>`,f:`<button class="btn" onclick="toast('Follow-up sent for stalled documents','ok');closeD()">Follow Up on Stalled Documents</button>`},
  notices:{t:'BMS Notices — No Active Content',s:'web.hisociety.lockated.com/bms/hisoc-notice-list',b:`<div class="dsec"><div class="dst">Current status</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--amb)">No notices have been published for Veda Gardens. The Notices section supports: Notice Heading, Notice Type, Block targeting, Expiry Time, and Important flag. Regular community notices significantly improve resident engagement.</div></div><div class="dsec"><div class="dst">Suggested notice types</div><div class="drow"><span class="dl">Maintenance schedule</span><span class="dv">Weekly</span></div><div class="drow"><span class="dl">Society updates</span><span class="dv">Bi-weekly</span></div><div class="drow"><span class="dl">Event announcements</span><span class="dv">As needed</span></div></div>`,f:`<button class="btn" onclick="toast('Notice composer opened','ok');closeD()">Publish a Notice</button>`},
  events:{t:'BMS Events — No Events Scheduled',s:'web.hisociety.lockated.com/bms/hisoc-event-list',b:`<div class="dsec"><div class="dst">Events module supports</div><div class="drow"><span class="dl">Event Name</span><span class="dv">Text</span></div><div class="drow"><span class="dl">Event At</span><span class="dv">Venue</span></div><div class="drow"><span class="dl">Event Date + Time</span><span class="dv">Scheduled</span></div><div class="drow"><span class="dl">Show on Home</span><span class="dv">Resident app visibility</span></div><div class="drow"><span class="dl">Publish status</span><span class="dv">Draft or Live</span></div></div>`,f:`<button class="btn" onclick="toast('Event creator opened','ok');closeD()">Create an Event</button>`},
  polls:{t:'4 Polls — All Closed, 0% Participation',s:'communication/polls',b:`<div class="dsec"><div class="dst">Polls created</div><div class="drow"><span class="dl">Test Poll</span><span class="dv">0 votes · Closed</span></div><div class="drow"><span class="dl">test polls 5454</span><span class="dv">1 vote · Closed</span></div><div class="drow"><span class="dl">Kids Play Area Poll</span><span class="dv">0 votes · Closed</span></div><div class="drow"><span class="dl">Poll (generic)</span><span class="dv">0 votes · Closed</span></div></div><div class="dsec"><div class="dst">Why participation is low</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px">Polls were created in April 2026 with short end-date windows and generic topics — that's part of the story. But app adoption is only 48% society-wide, and just 17% in Tower T3. A meaningful share of residents were never in a position to see these polls at all.</div></div>`,f:`<button class="btn" onclick="toast('New poll creator opened','ok');closeD()">Create New Poll</button>`},
  app_adoption:{t:'Resident App Adoption — 48% Overall',s:'BMS → Groups · Registered residents by tower',b:`<div class="dsec"><div class="dst">By tower</div><div class="drow"><span class="dl">Tower T2</span><span class="dv" style="color:var(--for)">224 of 260 (86%)</span></div><div class="drow"><span class="dl">Tower T1</span><span class="dv" style="color:var(--sky)">196 of 280 (70%)</span></div><div class="drow"><span class="dl">Tower FM</span><span class="dv" style="color:var(--crim)">78 of 320 (24%)</span></div><div class="drow"><span class="dl">Tower T3</span><span class="dv" style="color:var(--crim)">45 of 264 (17%)</span></div></div><div class="dsec"><div class="dst">What this explains</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">Poll participation reads as "0% everywhere" — but if Tower T3 only has 17% of residents on the app, most T3 residents literally never saw the poll notification. This reframes the fix: onboarding first, poll redesign second.</div></div><div class="dsec"><div class="dst">Recommended sequence</div><div style="font-size:11px;line-height:1.7">1. Run a targeted onboarding push in Tower T3 and FM (lowest adoption)<br>2. Re-launch a poll only after adoption improves, to get a true read on engagement<br>3. Track adoption alongside every future poll result — not as a separate metric</div></div>`,f:`<button class="btn" onclick="toast('Onboarding campaign started for T3, FM','ok');closeD()">Launch Targeted Onboarding — T3 &amp; FM</button>`},
  parking_all:{t:'6 Registered Parking Slots',s:'Across 3 towers · Veda Gardens',b:`<div class="dsec"><div class="dst">By tower</div><div class="drow"><span class="dl">Tower T3</span><span class="dv">3 vehicles</span></div><div class="drow"><span class="dl">Tower FM</span><span class="dv">2 vehicles</span></div><div class="drow"><span class="dl">Tower T4</span><span class="dv">1 vehicle</span></div><div class="drow"><span class="dl">Tower T1, T2</span><span class="dv" style="color:var(--crim)">0 — no coverage</span></div></div><div class="dsec"><div class="dst">By vehicle type</div><div class="drow"><span class="dl">4-Wheeler</span><span class="dv">4 (67%)</span></div><div class="drow"><span class="dl">2-Wheeler</span><span class="dv">2 (33%)</span></div></div>`,f:`<button class="btn" onclick="toast('Full parking list opened','ok');closeD()">Open Parking Module</button>`},
  parking_type:{t:'Parking Type Distribution',s:'SUV · Hatchback · Bike',b:`<div class="dsec"><div class="dst">By parking type</div><div class="drow"><span class="dl">SUV</span><span class="dv">2 slots (33%)</span></div><div class="drow"><span class="dl">Hatchback</span><span class="dv">2 slots (33%)</span></div><div class="drow"><span class="dl">Bike</span><span class="dv">1 slot (17%)</span></div><div class="drow"><span class="dl">Mismatched (2W tagged as SUV)</span><span class="dv" style="color:var(--crim)">1 slot (17%)</span></div></div><div class="dsec"><div class="dst">Why it matters</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px">There's no distinct "2-Wheeler" parking type in the system yet — which is likely why slot P1 ended up mistagged as SUV. Adding this type would prevent future mismatches.</div></div>`,f:`<button class="btn" onclick="toast('Slot type settings opened','ok');closeD()">Add 2-Wheeler Type</button>`},
  parking_mismatch:{t:'Data Mismatch — Slot P1',s:'FM · Office · Vehicle/Parking type conflict',b:`<div class="dflat"><div class="dflat-ico"><i data-lucide="map-pin" style="width:16px;height:16px"></i></div><div><div class="dflat-tower">FM · Office</div><div class="dflat-res">Slot P1 · No vehicle number or sticker on record</div></div></div><div class="dsec"><div class="dst">The conflict</div><div class="drow"><span class="dl">Vehicle Type (recorded)</span><span class="dv" style="color:var(--crim)">2 Wheeler</span></div><div class="drow"><span class="dl">Parking Type (recorded)</span><span class="dv" style="color:var(--crim)">SUV</span></div></div><div class="dsec"><div class="dst">Likely explanation</div><div style="font-size:11px;line-height:1.7">Most likely this slot was originally allocated to a 4-Wheeler (SUV) and later reassigned to a 2-Wheeler resident without updating the Parking Type field. The missing Vehicle Number and Sticker Number support this — the record looks incomplete, not just mistagged.</div></div>`,f:`<button class="btn" onclick="toast('Slot P1 correction saved','ok');closeD()">Correct This Slot</button>`},
  parking_slot_det:{t:'Parking Slot Detail',s:'Full slot record',b:`<div class="dsec"><div class="dst">Slot record</div><div class="drow"><span class="dl">Slot Number</span><span class="dv">PS-T4</span></div><div class="drow"><span class="dl">Tower / Flat</span><span class="dv">T4 · 101</span></div><div class="drow"><span class="dl">Vehicle Number</span><span class="dv">MH 47 G 6787</span></div><div class="drow"><span class="dl">Vehicle Type</span><span class="dv">4 Wheeler</span></div><div class="drow"><span class="dl">Parking Type</span><span class="dv">Hatchback</span></div><div class="drow"><span class="dl">Sticker Number</span><span class="dv">T4-PS4</span></div><div class="drow"><span class="dl">Status</span><span class="dv" style="color:var(--for)">Active</span></div></div>`,f:`<button class="btn" onclick="toast('Slot editor opened','ok');closeD()">Edit Slot</button>`},
  notifications:{t:'System Notifications — Last 30 Days',s:'42 delivered of 45 sent · 93%',b:`<div class="dsec"><div class="dst">By channel</div><div class="drow"><span class="dl">Push</span><span class="dv" style="color:var(--for)">22/22 delivered (100%)</span></div><div class="drow"><span class="dl">Email</span><span class="dv" style="color:var(--for)">14/14 delivered (100%)</span></div><div class="drow"><span class="dl">SMS</span><span class="dv" style="color:var(--crim)">7/9 delivered (78%)</span></div></div><div class="dsec"><div class="dst">What this tracks</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--sky)">Notifications are system-triggered alerts (payment reminders, ticket updates, event reminders) — distinct from Notices, which are manually published announcements. This metric tracks delivery success, not read engagement.</div></div><div class="dsec"><div class="dst">Root cause</div><div style="font-size:11px;line-height:1.7">All 3 failures this month were SMS. This pattern (isolated to one channel, not random) usually points to a phone number formatting issue for specific residents rather than a carrier-wide problem.</div></div>`,f:`<button class="btn" onclick="toast('Phone number audit started','ok');closeD()">Audit SMS Numbers</button>`},
  quarantine:{t:'Quarantine Tracker — 4 Active Cases',s:'2 In Quarantine · 2 Under Observation · Avg duration 12 days',b:`<div class="dsec"><div class="dst">Active now</div><div class="drow"><span class="dl">Godrej Living · FM-Office</span><span class="dv" style="color:var(--er)">COVID-19 · Day 12</span></div><div class="drow"><span class="dl">Ashik Bhattacharya · GL-Team</span><span class="dv" style="color:var(--er)">COVID-19 · Day 7</span></div><div class="drow"><span class="dl">Deepak Gupta · A-104</span><span class="dv" style="color:var(--amb)">Flu · Under Observation</span></div><div class="drow"><span class="dl">Team Member GL</span><span class="dv" style="color:var(--amb)">Flu · Under Observation</span></div></div><div class="dsec"><div class="dst">Recently recovered</div><div class="drow"><span class="dl">Ubaid Hashmat · A-101</span><span class="dv" style="color:var(--for)">14 days · Recovered</span></div><div class="drow"><span class="dl">Prashant Sangle · A-101</span><span class="dv" style="color:var(--for)">14 days · Recovered</span></div></div><div class="dsec"><div class="dst">Analysis</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--amb)">Average completed quarantine duration this period is 12 days. Godrej Living is already at day 12 — due for a clearance check-up now rather than continued open-ended isolation.</div></div>`,f:`<button class="btn" onclick="toast('Clearance check-up scheduled','ok');closeD()">Schedule Clearance Check-up</button>`},
  directory_all:{t:'Business Directory — 6 Vendors',s:'4 Active · 2 Inactive (1 duplicate)',b:`<div class="dsec"><div class="dst">Active vendors</div><div class="drow"><span class="dl">Lockated</span><span class="dv" style="color:var(--for)">Milk Supply</span></div><div class="drow"><span class="dl">New</span><span class="dv" style="color:var(--for)">Interior Painting</span></div><div class="drow"><span class="dl">Regal Super Market</span><span class="dv" style="color:var(--for)">Grocery Supplier</span></div><div class="drow"><span class="dl">title</span><span class="dv" style="color:var(--for)">Interior Painting</span></div></div><div class="dsec"><div class="dst">Needs cleanup</div><div class="drow"><span class="dl">SafeGuard Security Solutions 2</span><span class="dv" style="color:var(--crim)">Inactive — fully disabled</span></div><div class="drow"><span class="dl">Lockated (duplicate entry)</span><span class="dv" style="color:var(--crim)">Inactive — conflicts with active listing</span></div></div><div class="dsec"><div class="dst">Recommendation</div><div style="font-size:11px;line-height:1.7">Merge the two "Lockated" entries into one Active listing, and remove SafeGuard if that vendor relationship has ended. A resident searching the directory today could easily call the wrong or disconnected number.</div></div>`,f:`<button class="btn" onclick="toast('Duplicate merge started','ok');closeD()">Merge Duplicate Listing</button>`},
  vis_today:{t:'234 Visitors Today',s:'All SmartSecure visitor types',b:`<div class="dsec"><div class="dst">By guest type</div><div class="drow"><span class="dl">Guest</span><span class="dv">~98</span></div><div class="drow"><span class="dl">Support Staff</span><span class="dv">~54</span></div><div class="drow"><span class="dl">Delivery</span><span class="dv">~38</span></div><div class="drow"><span class="dl">Contractor</span><span class="dv">~32</span></div><div class="drow"><span class="dl">Other</span><span class="dv">~12</span></div></div><div class="dsec"><div class="dst">By gate</div><div class="drow"><span class="dl">Komal Gate</span><span class="dv">98</span></div><div class="drow"><span class="dl">Devash Gate</span><span class="dv">72</span></div><div class="drow"><span class="dl">Dinash Gate</span><span class="dv">64</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  golden_tickets:{t:'⭐ Golden Tickets Open — 4',s:'Priority tickets for senior/differently-abled residents',b:`<div class="dsec"><div class="dst">What are Golden Tickets?</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--amb)">Golden Tickets are flagged by the system when a complaint is raised by a Senior Citizen, Differently-abled Resident, or Pregnant Resident. They appear at the top of the helpdesk queue and trigger faster escalation timelines than standard P1 tickets.</div></div><div class="dsec"><div class="dst">Open golden tickets</div><div class="drow"><span class="dl">#S010-10045 · Electrical</span><span class="dv" style="color:var(--crim)">P1 · Work in Progress</span></div><div class="drow"><span class="dl">#S010-10038 · Housekeeping</span><span class="dv" style="color:var(--crim)">P1 · Pending</span></div><div class="drow"><span class="dl">#S010-10022 · Civil</span><span class="dv" style="color:var(--amb)">P2 · Pending</span></div><div class="drow"><span class="dl">#S010-10019 · Plumbing</span><span class="dv" style="color:var(--amb)">P2 · Pending</span></div></div>`,f:`<button class="btn" onclick="toast('Golden ticket queue opened','ok');closeD()">View All Golden Tickets</button>`},
  failed_payments:{t:'1 Failed Payment — Follow Up Required',s:'CMS Payments · Payment Status: failure',b:`<div class="dsec"><div class="dst">Failed payment detail</div><div class="drow"><span class="dl">Resident</span><span class="dv">Govind Patil</span></div><div class="drow"><span class="dl">Tower / Flat</span><span class="dv">T1 — 201</span></div><div class="drow"><span class="dl">Type</span><span class="dv">ClubMember</span></div><div class="drow"><span class="dl">Amount</span><span class="dv" style="color:var(--crim)">₹1,000</span></div><div class="drow"><span class="dl">Transaction ID</span><span class="dv">14488288688</span></div><div class="drow"><span class="dl">Date</span><span class="dv">05 May 2026</span></div></div><div class="dsec"><div class="dst">Recommended action</div><div style="font-size:11px;line-height:1.7">Contact Govind Patil directly and request payment retry via UPI or arrange offline collection. The ClubMember plan may be suspended until payment clears. Update membership status to Pending until resolved.</div></div>`,f:`<button class="btn" onclick="toast('Resident contact initiated','ok');closeD()">Contact Resident</button><button class="btng" onclick="toast('Offline payment recorded','ok');closeD()">Record Offline Payment</button>`},
  expiring_mem:{t:'Memberships Expiring — Renewal Needed',s:'End Date within 30 days or already expired',b:`<div class="dsec"><div class="dst">Already expired</div><div class="drow"><span class="dl">Ajay Ghenand (FM-Office)</span><span class="dv" style="color:var(--er)">Summer Plan · Expired 8 May</span></div><div class="drow"><span class="dl">Sagar Patil (FM-Offices)</span><span class="dv" style="color:var(--er)">Summer Plan · Expired 31 May</span></div></div><div class="dsec"><div class="dst">Expiring within 30 days</div><div class="drow"><span class="dl">Basic Plan Gold members</span><span class="dv" style="color:var(--amb)">Expiry: Oct–Nov 2026 · Multiple</span></div></div><div class="dsec"><div class="dst">Recommended action</div><div style="font-size:11px;line-height:1.7">Send renewal reminder via Notice or direct message 14 days before End Date. Members lose facility booking access on the expiry date. The Test plan members (₹1,000/month) should be reviewed — these are likely demo accounts.</div></div>`,f:`<button class="btn" onclick="toast('Renewal reminders sent','ok');closeD()">Send Renewal Reminders</button>`},
  staff_scheduled:{t:'34 Staff Scheduled Today',s:'Across all categories',b:`<div class="dsec"><div class="dst">By category</div><div class="drow"><span class="dl">Housekeeping</span><span class="dv">14</span></div><div class="drow"><span class="dl">Security</span><span class="dv">10</span></div><div class="drow"><span class="dl">Maintenance</span><span class="dv">6</span></div><div class="drow"><span class="dl">Gardening</span><span class="dv">4</span></div></div><div class="dsec"><div class="dst">By shift</div><div class="drow"><span class="dl">Morning</span><span class="dv">12</span></div><div class="drow"><span class="dl">Afternoon</span><span class="dv">10</span></div><div class="drow"><span class="dl">Evening</span><span class="dv">9</span></div><div class="drow"><span class="dl">Night</span><span class="dv">3</span></div></div>`,f:`<button class="btng" onclick="closeD()">Close</button>`},
  staff_present:{t:'29 Staff Present Today',s:'4 late arrivals · 85% attendance',b:`<div class="dsec"><div class="dst">Attendance</div><div class="drow"><span class="dl">On-time</span><span class="dv" style="color:var(--for)">25</span></div><div class="drow"><span class="dl">Late</span><span class="dv" style="color:var(--amb)">4</span></div><div class="drow"><span class="dl">Absent</span><span class="dv" style="color:var(--crim)">5</span></div></div><div class="dsec"><div class="dst">Late arrivals</div><div class="drow"><span class="dl">Housekeeping staff ×2</span><span class="dv">15–20 min late</span></div><div class="drow"><span class="dl">Security staff ×2</span><span class="dv">10 min late</span></div></div>`,f:`<button class="btn" onclick="toast('Attendance log opened','ok');closeD()">View Attendance Log</button>`},
  staff_absent:{t:'5 Staff Absent Today',s:'Needs backfill · Housekeeping most affected',b:`<div class="dsec"><div class="dst">Absences by category</div><div class="drow"><span class="dl">Housekeeping</span><span class="dv" style="color:var(--crim)">3 absent</span></div><div class="drow"><span class="dl">Security</span><span class="dv" style="color:var(--amb)">1 absent</span></div><div class="drow"><span class="dl">Maintenance</span><span class="dv" style="color:var(--amb)">1 absent</span></div></div><div class="dsec"><div class="dst">Downstream impact</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">3 Housekeeping staff absent today will likely show up as slower ticket response in the Helpdesk tab over the next 24 hours — Housekeeping is also your highest-volume ticket category.</div></div>`,f:`<button class="btn" onclick="toast('Backfill request sent','ok');closeD()">Arrange Backfill</button>`},
  staff_gap:{t:'Evening Shift — 3 Staff Short',s:'Overlaps with peak visitor traffic (5–7 PM)',b:`<div class="dsec"><div class="dst">The compounding problem</div><div style="font-size:11px;line-height:1.7;background:var(--cream);padding:10px;border-radius:8px;border-left:2px solid var(--er)">The Evening shift (5–7 PM) has both the lowest staff coverage (65%) of the day AND the highest visitor traffic volume (Security tab). These two facts compound each other directly — fewer staff are available exactly when the most gate clearance work is needed.</div></div><div class="dsec"><div class="dst">Shift coverage today</div><div class="drow"><span class="dl">Morning</span><span class="dv" style="color:var(--for)">92%</span></div><div class="drow"><span class="dl">Afternoon</span><span class="dv" style="color:var(--for)">88%</span></div><div class="drow"><span class="dl">Evening</span><span class="dv" style="color:var(--crim)">65%</span></div><div class="drow"><span class="dl">Night</span><span class="dv" style="color:var(--for)">90%</span></div></div>`,f:`<button class="btn" onclick="toast('Shift reassignment opened','ok');closeD()">Reassign or Backfill Evening Shift</button>`},
  default:{t:'Detail View',s:'',b:`<div style="padding:28px;text-align:center;color:var(--sto);font-size:12px">Detail view available with live data from BMS.</div>`,f:`<button class="btng" onclick="closeD()">Close</button>`}
};
